package edu.northeastern.cs5010.backend.audit;

import edu.northeastern.cs5010.backend.api.ApiException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.net.InetAddress;
import java.net.UnknownHostException;
import java.time.Clock;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;

/**
 * The only writer of {@code audit_logs} (AU-12). Records are generated by the service layer; there is no
 * setting to turn logging off.
 *
 * <p>{@link #record} is for successful changes: if the record cannot be written it throws, and the caller
 * undoes the change. {@link #recordFailure} is for failures: it never throws, so the original error still
 * reaches the user, and it writes the event to the application log if MongoDB refuses it.
 */
@Service
public class AuditService {
    public static final int SCHEMA_VERSION = 1;
    private static final int MAX_TEXT = 500;
    private static final Logger log = LoggerFactory.getLogger(AuditService.class);

    private final AuditRepository repository;
    private final Clock clock;
    private final String host;
    private final String actor;

    @Autowired
    public AuditService(AuditRepository repository) {
        this(repository, Clock.systemUTC());
    }

    AuditService(AuditRepository repository, Clock clock) {
        this.repository = repository;
        this.clock = clock;
        this.host = hostName();
        this.actor = "local-user:" + System.getProperty("user.name", "unknown");
    }

    /**
     * Writes a SUCCESS record.
     *
     * @return the new record's id
     * @throws ApiException {@code 500 AUDIT_WRITE_FAILED} when the record could not be stored
     */
    public String record(AuditEventType type, Class<?> source, AuditRecord.Refs refs, Map<String, ?> details) {
        AuditRecord record = build(type, source, AuditRecord.Outcome.SUCCESS, refs, details, null);
        try {
            return repository.insert(record).id();
        } catch (RuntimeException e) {
            log.error("Audit write failed for {} {}: {}", type, refs, e.toString());
            throw new ApiException(HttpStatus.INTERNAL_SERVER_ERROR, "AUDIT_WRITE_FAILED",
                    "The action could not be recorded",
                    "The action was not completed because its audit record could not be saved. "
                            + "Check that MongoDB is running and try again.");
        }
    }

    /** Writes a FAILURE record. Returns its id, or {@code null} if it could not be stored. */
    public String recordFailure(AuditEventType type, Class<?> source, AuditRecord.Refs refs, Map<String, ?> details,
                                String errorCode, String errorMessage) {
        AuditRecord record = build(type, source, AuditRecord.Outcome.FAILURE, refs, details,
                new AuditRecord.Failure(errorCode, truncate(errorMessage)));
        try {
            return repository.insert(record).id();
        } catch (RuntimeException e) {
            log.error("Audit write failed; event not stored: type={} refs={} error={} message={} cause={}",
                    type, refs, errorCode, errorMessage, e.toString());
            return null;
        }
    }

    private AuditRecord build(AuditEventType type, Class<?> source, AuditRecord.Outcome outcome,
                              AuditRecord.Refs refs, Map<String, ?> details, AuditRecord.Failure error) {
        Map<String, Object> copy = new LinkedHashMap<>();
        if (details != null) {
            details.forEach((k, v) -> copy.put(k, v instanceof String s ? truncate(s) : v));
        }
        return new AuditRecord(UUID.randomUUID().toString(), SCHEMA_VERSION, Instant.now(clock), type,
                "backend." + source.getSimpleName(), host, actor, outcome,
                refs == null ? AuditRecord.Refs.NONE : refs, copy, error);
    }

    private static String truncate(String text) {
        if (text == null || text.length() <= MAX_TEXT) {
            return text;
        }
        return text.substring(0, MAX_TEXT) + "…(truncated)";
    }

    private static String hostName() {
        try {
            return InetAddress.getLocalHost().getHostName();
        } catch (UnknownHostException e) {
            return "unknown";
        }
    }
}
